import {sourceMaterial,bank,finances,snapshot,portfolio,row,bki,reconciliationFinding,source,inn,date} from '../credit-lab/builders.mjs';
import {adaptRiskFacts} from '../../../lib/credit-engine/risk/facts.ts';
import {evaluateRiskFacts} from '../../../lib/credit-engine/risk/engine.ts';
export {finances,snapshot,portfolio,row,bki,reconciliationFinding,source,inn,date};
export const metric=(code,value,unit='RUB')=>({code,version:'PRESCORE-BANK-METRICS-2.0.0-SHADOW',value,unit,status:value===null?'UNKNOWN':'KNOWN',confidence:'HIGH',periodFrom:'2026-01-01',periodTo:date,transactionCount:10,sourceCount:1,calculationBasis:'Synthetic canonical Block 4 output',includedCategories:[],warnings:[]});
export function material(){const m=sourceMaterial(),b=bank();m.analysis.metricsV2=b;Object.assign(b.operating,{operatingCashReceipts:metric('BSM-OPER-001',9000000),operatingReceiptsVolatility:metric('BSM-OPER-VOL',.1,'RATIO'),seasonalityEligibility:metric('BSM-OPER-015',0,'COUNT'),seasonalityStatus:'INSUFFICIENT_HISTORY'});b.liquidity.averageDailyBalance=metric('BSM-LIQ-AVG',1000000);b.suppliers={supplierTop1:metric('BSM-SUP-001',.2,'RATIO')};b.ownerFunding={ownerContributionAmount:metric('BSM-OWNER-001',0)};b.financing={ownerLoanInflow:metric('BSM-OWNER-LOAN',0),factoringInflow:metric('BSM-FACTOR',0)};b.ownerOutflows={ownerWithdrawalAmount:metric('BSM-OWNER-OUT',0)};b.tax={taxPaymentMonthShare:metric('BSM-TAX-SHARE',1,'RATIO')};b.monthly=Array.from({length:6},(_,i)=>({month:`2026-0${i+1}`,coverage:'FULL',operatingReceipts:1500000}));b.customers.directGroups=[{key:'synthetic:customer',displayName:'Синтетический заказчик',inn:'9900000002',amount:5400000,share:.6,identityConfidence:'HIGH'}];Object.assign(m.companyProfile.company,{registrationDate:'2020-06-30',region:'Синтетический регион',okvedCode:'62.01'});m.companyProfile.contracts={totalCount:0,activeCount:0,completedCount:0,totalAmount:0,activeAmount:0,topCustomerShare:null,items:[]};return m;}
export const field=(value,extra={})=>({value,source:'CLIENT_DECLARED',status:value===null?'UNKNOWN':'KNOWN',confidence:'MEDIUM',evidenceAsOf:date,warnings:[],...extra});
export const financingCase=(extra={})=>({caseId:'synthetic-case',companyInn:inn,asOfDate:date,requestedAmount:field(1000000),requestedTermMonths:field(12),financingPurpose:field('WORKING_CAPITAL'),requestedProduct:field('CREDIT_LINE'),urgency:field('WITHIN_30_DAYS'),...extra});
export function input(m=material(),c){const facts=adaptRiskFacts({analysis:m.analysis,companyProfile:m.companyProfile,asOfDate:date});return {analysis:m.analysis,companyProfile:m.companyProfile,asOfDate:date,riskAssessment:evaluateRiskFacts({companyInn:inn,asOfDate:date,facts}),...(c?{financingCase:c}:{})};}
export function activeContract(m){m.companyProfile.contracts={totalCount:1,activeCount:1,completedCount:0,totalAmount:10000000,activeAmount:10000000,topCustomerShare:1,items:[{number:'SYN-2026/1',customer:'Синтетический заказчик',law:'44-ФЗ',amount:10000000,signedAt:'2026-01-01',executionAt:'2027-12-31',status:'ACTIVE'}]};}
// Independent reported RiskFacts are an approved canonical boundary for focused BKI cases.
export function bkiFactsInput(overdue,history){const x=input();x.riskAssessment.facts=x.riskAssessment.facts.filter(f=>!f.semanticCode.startsWith('BKI_'));for(const[semanticCode,value]of [['BKI_OVERDUE',overdue],['BKI_HISTORY_DAYS',history]])x.riskAssessment.facts.push({factId:`synthetic:${semanticCode}`,semanticCode,domain:'CREDIT_HISTORY',companyInn:inn,value,status:value===null?'UNKNOWN':'KNOWN',confidence:'HIGH',unit:semanticCode==='BKI_OVERDUE'?'RUB':'DAYS',origin:'REPORTED',period:{from:null,to:null,asOf:date},sourceIds:['synthetic:BKI'],sourceTypes:['BKI'],subjectKey:'synthetic-contract',calculationBasis:semanticCode==='BKI_HISTORY_DAYS'?'Reported historical maximum days; not current age':'Explicitly reported current overdue',warnings:[],evidence:[{evidenceId:`synthetic:e:${semanticCode}`,sourceId:'synthetic:BKI',sourceType:'BKI',metricCode:null,factCode:semanticCode,portfolioObligationId:null,reconciliationFindingId:null,value,unit:null,periodFrom:null,periodTo:null,asOf:date,confidence:'HIGH',calculationBasis:'Explicit synthetic reported field'}]});x.riskAssessment=evaluateRiskFacts({companyInn:inn,asOfDate:date,facts:x.riskAssessment.facts});return x;}
